input.content:
"""Load the frozen boundary contracts in ``tests/contracts/<id>.<Symbol>/``.

Each folder holds ``schema.json`` (JSON Schema) and ``samples/<case>.json``, one per case the
contract names. A schema whose ``title`` is a dotted ``rllab`` name builds its samples into that
Python type (``sample``). A Protocol's folder adds ``double.py``, a replay double serving its
recording; a boundary function's folder adds ``fake.py``, a fake serving its fixtures.

Consumers' tests import this module as ``tests.contracts.contracts``:

    from tests.contracts.contracts import double, fake, sample

    spec = sample("core.WorldSpec", "snake-default")
    world = double("core.World").ReplayWorld()
    run_train = fake("train.run_train").run_train
"""

import dataclasses
import importlib
import importlib.util
import json
import sys
import types
import typing
from collections.abc import Mapping
from datetime import datetime, timedelta
from pathlib import Path
from types import ModuleType
from typing import Any

import numpy as np

ROOT = Path(__file__).parent

# ------------------------------------------------------------------------------------- folders


def folders() -> list[Path]:
    """Every contract folder."""
    return sorted(p for p in ROOT.iterdir() if p.is_dir() and "." in p.name)


def folder(symbol: str) -> Path:
    path = ROOT / symbol
    if not path.is_dir():
        raise LookupError(f"no contract folder for {symbol}")
    return path


def read_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def schema(symbol: str) -> dict[str, Any]:
    return read_json(folder(symbol) / "schema.json")  # type: ignore[no-any-return]


def cases(symbol: str) -> list[str]:
    return sorted(p.stem for p in (folder(symbol) / "samples").glob("*.json"))


def raw(symbol: str, case: str) -> Any:
    """A sample as parsed JSON."""
    path = folder(symbol) / "samples" / f"{case}.json"
    if not path.is_file():
        raise LookupError(f"{symbol} has no sample {case!r}; cases: {cases(symbol)}")
    return read_json(path)


def python_object(title: str) -> Any:
    """The ``rllab`` object a schema's ``title`` names, e.g. ``rllab.core.WorldSpec``."""
    module_name, _, name = title.rpartition(".")
    return getattr(importlib.import_module(module_name), name)


def sample(symbol: str, case: str) -> Any:
    """A sample built into the Python type its schema's ``title`` names."""
    return build(python_object(schema(symbol)["title"]), raw(symbol, case))


def _module(symbol: str, name: str) -> ModuleType:
    """A folder's ``double.py`` or ``fake.py``, loaded by path (folder names hold a dot)."""
    key = f"contracts_{symbol.replace('.', '_')}_{name}"
    if key in sys.modules:
        return sys.modules[key]
    spec = importlib.util.spec_from_file_location(key, folder(symbol) / f"{name}.py")
    if spec is None or spec.loader is None:
        raise LookupError(f"{symbol} has no {name}.py")
    module = importlib.util.module_from_spec(spec)
    sys.modules[key] = module
    spec.loader.exec_module(module)
    return module


def double(symbol: str) -> ModuleType:
    """The replay double module of a Protocol or class contract."""
    return _module(symbol, "double")


def fake(symbol: str) -> ModuleType:
    """The fake module of a boundary function."""
    return _module(symbol, "fake")


# ------------------------------------------------------------------------------- JSON -> types


def build(tp: Any, data: Any) -> Any:  # noqa: C901, PLR0911, PLR0912 - one branch per type kind
    """Build parsed JSON into the Python type ``tp``; ``TypeError`` if it doesn't fit."""
    if isinstance(tp, typing.TypeAliasType):
        return build(tp.__value__, data)
    origin, args = typing.get_origin(tp), typing.get_args(tp)
    if tp is Any or tp is object:
        return data
    if origin is np.ndarray:
        return to_array(data)
    if dataclasses.is_dataclass(tp) and isinstance(tp, type):
        return _build_dataclass(tp, data)
    if origin in (types.UnionType, typing.Union):
        return _build_union(args, data)
    if origin is typing.Literal:
        if data not in args:
            raise TypeError(f"{data!r} is not one of {args}")
        return data
    if origin is tuple:
        return _build_tuple(args, data)
    if origin in (Mapping, dict):
        _expect(data, dict, tp)
        return {key: build(args[1], value) for key, value in data.items()}
    if tp is Path:
        return Path(_expect(data, str, tp))
    if tp is datetime:
        return datetime.fromisoformat(_expect(data, str, tp))
    if tp is timedelta:
        return timedelta(seconds=_expect(data, (int, float), tp))
    if tp is float:
        return float(_expect(data, (int, float), tp))
    if tp in (int, str, bool):
        return _expect(data, tp, tp)
    raise TypeError(f"no JSON form for {tp!r}")


def to_array(data: Any) -> np.ndarray:
    """Nested lists as a NumPy array; floats become float32, the contract's array dtype."""
    array = np.asarray(data)
    return array.astype(np.float32) if array.dtype == np.float64 else array


def _expect(data: Any, kinds: Any, tp: Any) -> Any:
    bad_bool = isinstance(data, bool) and bool not in (kinds if isinstance(kinds, tuple) else (kinds,))
    if bad_bool or not isinstance(data, kinds):
        raise TypeError(f"{data!r} is not a {tp!r}")
    return data


def _build_dataclass(cls: type, data: Any) -> Any:
    _expect(data, dict, cls)
    hints = typing.get_type_hints(cls)
    names = {f.name for f in dataclasses.fields(cls)}
    if unknown := set(data) - names:
        raise TypeError(f"{cls.__name__} has no fields {sorted(unknown)}")
    return cls(**{key: build(hints[key], value) for key, value in data.items()})


def _build_union(args: tuple[Any, ...], data: Any) -> Any:
    if data is None and type(None) in args:
        return None
    for arg in args:
        if arg is type(None):
            continue
        try:
            return build(arg, data)
        except TypeError:
            continue
    raise TypeError(f"{data!r} fits none of {args}")


def _build_tuple(args: tuple[Any, ...], data: Any) -> tuple[Any, ...]:
    _expect(data, list, tuple)
    if len(args) == 2 and args[1] is Ellipsis:  # noqa: PLR2004 - tuple[X, ...]
        return tuple(build(args[0], item) for item in data)
    if len(args) != len(data):
        raise TypeError(f"{data!r} does not have {len(args)} items")
    return tuple(build(arg, item) for arg, item in zip(args, data, strict=True))


def same(a: Any, b: Any) -> bool:
    """Equality that compares NumPy arrays by value, inside dataclasses and containers too."""
    if isinstance(a, np.ndarray) or isinstance(b, np.ndarray):
        return bool(np.array_equal(np.asarray(a), np.asarray(b)))
    if dataclasses.is_dataclass(a) and not isinstance(a, type):
        return type(a) is type(b) and all(
            same(getattr(a, f.name), getattr(b, f.name)) for f in dataclasses.fields(a)
        )
    if isinstance(a, Mapping) and isinstance(b, Mapping):
        return a.keys() == b.keys() and all(same(a[k], b[k]) for k in a)
    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
        return len(a) == len(b) and all(same(x, y) for x, y in zip(a, b, strict=True))
    return bool(a == b) or (a != a and b != b)  # NaN equals NaN in a recording  # noqa: PLR0124


# ------------------------------------------------------------------------- JSON Schema subset

KEYWORDS = {
    "$schema", "title", "description", "$comment", "$defs", "$ref", "type", "properties",
    "required", "additionalProperties", "items", "minItems", "maxItems", "enum", "const",
    "minimum", "maximum", "anyOf",
}  # fmt: skip
JSON_TYPES: dict[str, Any] = {
    "object": dict, "array": list, "string": str, "integer": int, "number": (int, float),
    "boolean": bool, "null": type(None),
}  # fmt: skip


def validate(instance: Any, schema_: Mapping[str, Any], root: Mapping[str, Any] | None = None, path: str = "$") -> list[str]:  # noqa: C901, PLR0912, E501 - one branch per keyword
    """Errors of ``instance`` against a JSON Schema using only ``KEYWORDS`` (an unknown one is
    an error, so no schema passes by using a keyword this checker would skip)."""
    root = schema_ if root is None else root
    if unknown := set(schema_) - KEYWORDS:
        return [f"{path}: unsupported schema keywords {sorted(unknown)}"]
    if "$ref" in schema_:
        name = schema_["$ref"].removeprefix("#/$defs/")
        return validate(instance, root["$defs"][name], root, path)
    if "type" in schema_ and not _is_type(instance, schema_["type"]):
        return [f"{path}: {instance!r} is not of type {schema_['type']}"]
    errors: list[str] = []
    if "enum" in schema_ and instance not in schema_["enum"]:
        errors.append(f"{path}: {instance!r} not in {schema_['enum']}")
    if "const" in schema_ and instance != schema_["const"]:
        errors.append(f"{path}: {instance!r} is not {schema_['const']!r}")
    if "minimum" in schema_ and instance < schema_["minimum"]:
        errors.append(f"{path}: {instance!r} < {schema_['minimum']}")
    if "maximum" in schema_ and instance > schema_["maximum"]:
        errors.append(f"{path}: {instance!r} > {schema_['maximum']}")
    if "anyOf" in schema_ and all(validate(instance, s, root, path) for s in schema_["anyOf"]):
        errors.append(f"{path}: {instance!r} matches no anyOf branch")
    if isinstance(instance, dict):
        errors += _validate_object(instance, schema_, root, path)
    if isinstance(instance, list):
        errors += _validate_array(instance, schema_, root, path)
    return errors


def _is_type(instance: Any, names: str | list[str]) -> bool:
    for name in [names] if isinstance(names, str) else names:
        if isinstance(instance, bool) and name in ("integer", "number"):
            continue
        if isinstance(instance, JSON_TYPES[name]):
            return True
    return False


def _validate_object(instance: dict[str, Any], schema_: Mapping[str, Any], root: Mapping[str, Any], path: str) -> list[str]:  # noqa: E501
    errors = [f"{path}: missing {key!r}" for key in schema_.get("required", []) if key not in instance]
    properties = schema_.get("properties", {})
    extra = schema_.get("additionalProperties", True)
    for key, value in instance.items():
        if key in properties:
            errors += validate(value, properties[key], root, f"{path}.{key}")
        elif extra is False:
            errors.append(f"{path}: unexpected {key!r}")
        elif isinstance(extra, Mapping):
            errors += validate(value, extra, root, f"{path}.{key}")
    return errors


def _validate_array(instance: list[Any], schema_: Mapping[str, Any], root: Mapping[str, Any], path: str) -> list[str]:  # noqa: E501
    errors: list[str] = []
    if len(instance) < schema_.get("minItems", 0):
        errors.append(f"{path}: fewer than {schema_['minItems']} items")
    if len(instance) > schema_.get("maxItems", len(instance)):
        errors.append(f"{path}: more than {schema_['maxItems']} items")
    if "items" in schema_:
        for i, item in enumerate(instance):
            errors += validate(item, schema_["items"], root, f"{path}[{i}]")
    return errors

