SCALARS: dict[Any, tuple[Any, Callable[[Any], Any]]] = {
    Path: (str, Path),
    datetime: (str, datetime.fromisoformat),
    timedelta: ((int, float), lambda seconds: timedelta(seconds=seconds)),
    float: ((int, float), float),
    int: (int, int),
    str: (str, str),
    bool: (bool, bool),
}


def build(tp: Any, data: Any) -> Any:
    """Build parsed JSON into the Python type ``tp``; ``TypeError`` if it doesn't fit."""
    while isinstance(tp, typing.TypeAliasType):
        tp = tp.__value__
    if tp is Any or tp is object:
        return data
    if tp in SCALARS:
        kinds, convert = SCALARS[tp]
        return convert(_expect(data, kinds, tp))
    if dataclasses.is_dataclass(tp) and isinstance(tp, type):
        return _build_dataclass(tp, data)
    return _build_generic(tp, data)


def _build_generic(tp: Any, data: Any) -> Any:
    origin, args = typing.get_origin(tp), typing.get_args(tp)
    if origin is np.ndarray:
        return to_array(data)
    if origin in (types.UnionType, typing.Union):
        return _build_union(args, data)
    if origin is typing.Literal:
        return _build_literal(args, data)
    if origin is tuple:
        return _build_tuple(args, data)
    if origin in (Mapping, dict):
        return {key: build(args[1], value) for key, value in _expect(data, dict, tp).items()}
    raise TypeError(f"no JSON form for {tp!r}")


def to_array(data: Any) -> np.ndarray:
    """Nested lists as a NumPy array; floats become float32, the contract's array dtype."""
    array = np.asarray(data)
    return array.astype(np.float32) if array.dtype == np.float64 else array


def _expect(data: Any, kinds: Any, tp: Any) -> Any:
    allowed = kinds if isinstance(kinds, tuple) else (kinds,)
    if (isinstance(data, bool) and bool not in allowed) or not isinstance(data, allowed):
        raise TypeError(f"{data!r} is not a {tp!r}")
    return data


def _build_dataclass(cls: type, data: Any) -> Any:
    _expect(data, dict, cls)
    hints = typing.get_type_hints(cls)
    names = {f.name for f in dataclasses.fields(cls)}
    if unknown := set(data) - names:
        raise TypeError(f"{cls.__name__} has no fields {sorted(unknown)}")
    return cls(**{key: build(hints[key], value) for key, value in data.items()})


def _build_union(args: tuple[Any, ...], data: Any) -> Any:
    if data is None and type(None) in args:
        return None
    for arg in args:
        try:
            return build(arg, data)
        except TypeError:
            continue
    raise TypeError(f"{data!r} fits none of {args}")


def _build_literal(args: tuple[Any, ...], data: Any) -> Any:
    if data not in args:
        raise TypeError(f"{data!r} is not one of {args}")
    return data


def _build_tuple(args: tuple[Any, ...], data: Any) -> tuple[Any, ...]:
    _expect(data, list, tuple)
    if len(args) == 2 and args[1] is Ellipsis:
        return tuple(build(args[0], item) for item in data)
    if len(args) != len(data):
        raise TypeError(f"{data!r} does not have {len(args)} items")
    return tuple(build(arg, item) for arg, item in zip(args, data, strict=True))


def same(a: Any, b: Any) -> bool:
    """Equality that compares NumPy arrays by value, inside dataclasses and containers too."""
    if isinstance(a, np.ndarray) or isinstance(b, np.ndarray):
        return bool(np.array_equal(np.asarray(a), np.asarray(b)))
    if dataclasses.is_dataclass(a) and not isinstance(a, type):
        return type(a) is type(b) and all(
            same(getattr(a, f.name), getattr(b, f.name)) for f in dataclasses.fields(a)
        )
    if isinstance(a, Mapping) and isinstance(b, Mapping):
        return a.keys() == b.keys() and all(same(a[k], b[k]) for k in a)
    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
        return len(a) == len(b) and all(same(x, y) for x, y in zip(a, b, strict=True))
    if isinstance(a, float) and isinstance(b, float) and math.isnan(a):
        return math.isnan(b)  # a recorded NaN (a failed run's value) equals NaN
    return bool(a == b)


# ------------------------------------------------------------------------- JSON Schema subset

KEYWORDS = frozenset({
    "$schema", "title", "description", "$comment", "$defs", "$ref", "type", "properties",
    "required", "additionalProperties", "items", "minItems", "maxItems", "enum", "const",
    "minimum", "maximum", "anyOf",
})  # fmt: skip
JSON_TYPES: dict[str, Any] = {
    "object": dict, "array": list, "string": str, "integer": int, "number": (int, float),
    "boolean": bool, "null": type(None),
}  # fmt: skip


def validate(
    instance: Any,
    schema_: Mapping[str, Any],
    root: Mapping[str, Any] | None = None,
    path: str = "$",
) -> list[str]:
    """Errors of ``instance`` against a JSON Schema that uses only ``KEYWORDS``.

    An unknown keyword is itself an error, so no schema passes by leaning on a keyword this
    checker would skip.
    """
    root = schema_ if root is None else root
    if unknown := set(schema_) - KEYWORDS:
        return [f"{path}: unsupported schema keywords {sorted(unknown)}"]
    if "$ref" in schema_:
        name = schema_["$ref"].removeprefix("#/$defs/")
        return validate(instance, root["$defs"][name], root, path)
    if "type" in schema_ and not _is_type(instance, schema_["type"]):
        return [f"{path}: {instance!r} is not of type {schema_['type']}"]
    errors = _validate_value(instance, schema_, path)
    if "anyOf" in schema_ and all(validate(instance, s, root, path) for s in schema_["anyOf"]):
        errors.append(f"{path}: {instance!r} matches no anyOf branch")
    if isinstance(instance, dict):
        errors += _validate_object(instance, schema_, root, path)
    if isinstance(instance, list):
        errors += _validate_array(instance, schema_, root, path)
    return errors


def _is_type(instance: Any, names: str | list[str]) -> bool:
    for name in [names] if isinstance(names, str) else names:
        if isinstance(instance, bool) and name in {"integer", "number"}:
            continue
        if isinstance(instance, JSON_TYPES[name]):
            return True
    return False


def _validate_value(instance: Any, schema_: Mapping[str, Any], path: str) -> list[str]:
    errors = []
    if "enum" in schema_ and instance not in schema_["enum"]:
        errors.append(f"{path}: {instance!r} not in {schema_['enum']}")
    if "const" in schema_ and instance != schema_["const"]:
        errors.append(f"{path}: {instance!r} is not {schema_['const']!r}")
    if "minimum" in schema_ and instance < schema_["minimum"]:
        errors.append(f"{path}: {instance!r} < {schema_['minimum']}")
    if "maximum" in schema_ and instance > schema_["maximum"]:
        errors.append(f"{path}: {instance!r} > {schema_['maximum']}")
    return errors


def _validate_object(
    instance: dict[str, Any], schema_: Mapping[str, Any], root: Mapping[str, Any], path: str
) -> list[str]:
    errors = [f"{path}: missing {k!r}" for k in schema_.get("required", []) if k not in instance]
    properties = schema_.get("properties", {})
    extra = schema_.get("additionalProperties", True)
    for key, value in instance.items():
        if key in properties:
            errors += validate(value, properties[key], root, f"{path}.{key}")
        elif extra is False:
            errors.append(f"{path}: unexpected {key!r}")
        elif isinstance(extra, Mapping):
            errors += validate(value, extra, root, f"{path}.{key}")
    return errors


def _validate_array(
    instance: list[Any], schema_: Mapping[str, Any], root: Mapping[str, Any], path: str
) -> list[str]:
    errors: list[str] = []
    if len(instance) < schema_.get("minItems", 0):
        errors.append(f"{path}: fewer than {schema_['minItems']} items")
    if len(instance) > schema_.get("maxItems", len(instance)):
        errors.append(f"{path}: more than {schema_['maxItems']} items")
    if "items" in schema_:
        for i, item in enumerate(instance):
            errors += validate(item, schema_["items"], root, f"{path}[{i}]")
    return errors

