"""Replay double of ``core.World``: the recorded 5-step snake episode from seed 42."""

from typing import Any

import numpy as np

from rllab.core import ActionError, Array, Box, Discrete, DrawState, EpisodeResult, Step, WorldSpec
from tests.contracts.contracts import build, raw, same


def check_actions(spec: WorldSpec, actions: Array) -> None:
    """Raise ``ActionError`` for the first agent whose action is outside ``spec.action``."""
    space = spec.action
    for agent, value in zip(spec.agents, np.asarray(actions), strict=True):
        if isinstance(space, Discrete):
            ok = value.shape == () and float(value).is_integer() and 0 <= value < space.n
        elif isinstance(space, Box):
            ok = value.shape == (space.dims,) and bool(np.all((value >= space.low) & (value <= space.high)))
        if not ok:
            raise ActionError(agent, value.tolist())


class ReplayWorld:
    """Serves a ``core.World`` recording (``samples/<case>.json``).

    ``strict`` (the default) asserts that ``reset`` gets the recorded seed and each ``step`` the
    recorded actions. ``strict=False`` serves the same steps for any seed and any in-format
    actions, so a loop can play many episodes against it. Out-of-format actions raise
    ``ActionError`` either way; a step past the recording's last (done) step raises
    ``RuntimeError``, as ``World`` does after ``done``.
    """

    def __init__(self, case: str = "snake-seed42", *, strict: bool = True) -> None:
        self._data: dict[str, Any] = raw("core.World", case)
        self.spec: WorldSpec = build(WorldSpec, self._data["spec"])
        self.strict = strict
        self._t: int | None = None

    def reset(self, seed: int) -> Step:
        if self.strict:
            assert seed == self._data["seed"], f"recorded seed {self._data['seed']}, got {seed}"
        self._t = 0
        return build(Step, self._data["reset"])

    def step(self, actions: Array) -> Step:
        check_actions(self.spec, actions)
        steps = self._data["steps"]
        if self._t is None or self._t >= len(steps):
            raise RuntimeError("step after the episode ended (or before reset)")
        recorded = steps[self._t]
        if self.strict:
            assert same(np.asarray(actions), np.asarray(recorded["actions"])), (
                f"step {self._t}: recorded actions {recorded['actions']}, got {actions}"
            )
        self._t += 1
        return build(Step, recorded["step"])

    def result(self) -> EpisodeResult:
        return build(EpisodeResult, self._data["result"])

    def draw(self) -> DrawState:
        return build(DrawState, self._data["draws"][self._t or 0])

