"""Replay double of ``worlds.CheckWorld``: the two-exit corridor and the 1-D target point."""

from typing import Any

import numpy as np

from rllab.core import Array, DrawState, EpisodeResult, Step, WorldSpec
from tests.contracts.contracts import build, double, raw, same, to_array


class ReplayCheckWorld:
    """Serves a ``worlds.CheckWorld`` recording: ``states``, ``best_actions`` and one episode.

    ``strict`` works as in ``core.World``'s ``ReplayWorld``: the recorded seed and actions only,
    or (``strict=False``) the recorded steps for any seed and in-format actions.
    """

    def __init__(self, case: str = "corridor", *, strict: bool = True) -> None:
        self._data: dict[str, Any] = raw("worlds.CheckWorld", case)
        self.spec: WorldSpec = build(WorldSpec, self._data["spec"])
        self.strict = strict
        self._t: int | None = None

    def states(self) -> Array:
        return to_array(self._data["states"])

    def best_actions(self) -> Array:
        return to_array(self._data["best_actions"])

    def reset(self, seed: int) -> Step:
        if self.strict:
            assert seed == self._data["seed"], f"recorded seed {self._data['seed']}, got {seed}"
        self._t = 0
        return build(Step, self._data["reset"])

    def step(self, actions: Array) -> Step:
        double("core.World").check_actions(self.spec, actions)
        steps = self._data["steps"]
        if self._t is None or self._t >= len(steps):
            raise RuntimeError("no recorded step left (the episode ended, or no reset)")
        recorded = steps[self._t]
        if self.strict:
            assert same(np.asarray(actions, np.float32), to_array(recorded["actions"])), (
                f"step {self._t}: recorded actions {recorded['actions']}, got {actions}"
            )
        self._t += 1
        return build(Step, recorded["step"])

    def result(self) -> EpisodeResult:
        if self._data["result"] is None:
            raise RuntimeError("the recorded episode has not ended")
        return build(EpisodeResult, self._data["result"])

    def draw(self) -> DrawState:
        return build(DrawState, self._data["draws"][self._t or 0])

